"""Collect results/q*.md + q*.json into results/REPORT.md and results/metrics.json."""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
from churnlab.common import RESULTS  # noqa: E402


def main():
    parts = sorted(RESULTS.glob("q*.md"))
    head = ["# Analysis report", "",
            "Generated by `python run_pipeline.py`. Each section is produced by one script in "
            "[`analysis/`](../analysis) and reads only [`data/`](../data).", ""]
    toc = [f"- [{p.stem.upper()}](#{p.stem}) {json.loads((RESULTS / (p.stem + '.json')).read_text())['title']}"
           for p in parts]
    body = []
    for p in parts:
        body += [f'<a id="{p.stem}"></a>', "", p.read_text(encoding="utf-8"), ""]
    (RESULTS / "REPORT.md").write_text("\n".join(head + toc + [""] + body), encoding="utf-8")
    metrics = {p.stem: json.loads(p.read_text())["metrics"] for p in sorted(RESULTS.glob("q*.json"))}
    (RESULTS / "metrics.json").write_text(json.dumps(metrics, indent=2), encoding="utf-8")
    print(f"wrote {RESULTS / 'REPORT.md'} and metrics.json ({len(parts)} sections)")


if __name__ == "__main__":
    main()
